import{_ as E,C as s,o as t,c as h,a7 as o,b as r,w as a,a as n,E as l,a8 as d}from"./chunks/framework.DmcojIVA.js";const y=JSON.parse('{"title":"分布式可观测性","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/distributed-system/observability.md","filePath":"development/common/distributed-system/observability.md","lastUpdated":1785428463000}'),c={name:"development/common/distributed-system/observability.md"};function u(A,e,b,m,g,p){const i=s("Mermaid");return t(),h("div",null,[e[2]||(e[2]=o('<h1 id="fen-bu-shi-ke-guan-ce-xing" tabindex="-1">分布式可观测性 <a class="header-anchor" href="#fen-bu-shi-ke-guan-ce-xing" aria-label="Permalink to &quot;分布式可观测性&quot;">​</a></h1><p>可观测性（Observability）是通过系统的外部输出理解其内部状态的能力。它不仅回答“系统是否异常”，还要支持继续追问“为什么异常”，尤其要能帮助排查事先没有为它单独配置告警的新问题。</p><h2 id="ke-guan-ce-xingjian-kong-yu-yao-ce" tabindex="-1">可观测性、监控与遥测 <a class="header-anchor" href="#ke-guan-ce-xingjian-kong-yu-yao-ce" aria-label="Permalink to &quot;可观测性、监控与遥测&quot;">​</a></h2><p>这三个概念经常混用，但关注点不同：</p><table tabindex="0"><thead><tr><th>概念</th><th>含义</th><th>典型问题</th></tr></thead><tbody><tr><td>遥测（Telemetry）</td><td>系统产生并传出的运行数据</td><td>采集了哪些指标、日志和 Span？</td></tr><tr><td>监控（Monitoring）</td><td>对已知状态进行测量、展示和告警</td><td>错误率是否超过阈值？</td></tr><tr><td>可观测性（Observability）</td><td>利用遥测数据理解系统行为的能力</td><td>为什么只有某个区域的新版本请求变慢？</td></tr></tbody></table><p>采集了大量数据，不代表系统已经具备可观测性。如果字段不一致、上下文无法关联、关键路径没有埋点，故障发生后依然无法回答问题。</p><h2 id="chang-jian-yao-ce-xin-hao" tabindex="-1">常见遥测信号 <a class="header-anchor" href="#chang-jian-yao-ce-xin-hao" aria-label="Permalink to &quot;常见遥测信号&quot;">​</a></h2><p>“指标、日志、链路追踪是可观测性三支柱”是有用的入门模型，但它不是严格边界。现代系统还会使用事件、持续性能剖析等信号。</p><table tabindex="0"><thead><tr><th>信号</th><th>擅长回答</th><th>数据特点</th><th>常见风险</th></tr></thead><tbody><tr><td>指标（Metrics）</td><td>是否异常、影响有多大</td><td>聚合时间序列，查询快</td><td>高基数标签导致成本失控</td></tr><tr><td>日志（Logs）</td><td>具体发生了什么</td><td>离散事件，细节丰富</td><td>噪声、敏感数据、存储量大</td></tr><tr><td>链路（Traces）</td><td>一次请求如何跨服务执行</td><td>请求级上下文和因果路径</td><td>采样不当、上下文断裂</td></tr><tr><td>事件（Events）</td><td>系统何时发生配置或状态变化</td><td>稀疏、语义明确</td><td>变更来源记录不完整</td></tr><tr><td>性能剖析（Profiles）</td><td>CPU 或内存消耗在哪段代码</td><td>代码级聚合样本</td><td>额外开销与符号管理</td></tr></tbody></table><p>三种核心信号的典型协作方式是：</p><blockquote><p>指标发现影响范围 → 链路定位慢服务或错误路径 → 日志解释具体业务状态和异常细节。</p></blockquote><h2 id="cong-mai-dian-dao-fen-xi-de-wan-zheng-guan-dao" tabindex="-1">从埋点到分析的完整管道 <a class="header-anchor" href="#cong-mai-dian-dao-fen-xi-de-wan-zheng-guan-dao" aria-label="Permalink to &quot;从埋点到分析的完整管道&quot;">​</a></h2>',12)),(t(),r(d,null,{default:a(()=>[l(i,{id:"mermaid-172",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E5%BA%94%E7%94%A8%E4%B8%8E%E5%9F%BA%E7%A1%80%E8%AE%BE%E6%96%BD%3Cbr%3E%E5%9F%8B%E7%82%B9%2F%E6%97%A5%E5%BF%97%2F%E6%8E%A2%E9%92%88%22%5D%20--%3E%20B%5B%22%E9%87%87%E9%9B%86%E4%B8%8E%E6%8E%A5%E6%94%B6%3Cbr%3EAgent%20%2F%20Collector%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E5%A4%84%E7%90%86%3Cbr%3E%E8%BF%87%E6%BB%A4%E3%80%81%E8%84%B1%E6%95%8F%E3%80%81%E9%87%87%E6%A0%B7%E3%80%81%E6%89%B9%E5%A4%84%E7%90%86%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E5%AD%98%E5%82%A8%E5%90%8E%E7%AB%AF%3Cbr%3EMetrics%20%2F%20Logs%20%2F%20Traces%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E4%BD%BF%E7%94%A8%3Cbr%3E%E6%9F%A5%E8%AF%A2%E3%80%81%E7%9C%8B%E6%9D%BF%E3%80%81%E5%91%8A%E8%AD%A6%E3%80%81%E6%8E%92%E9%9A%9C%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<blockquote><p>图示参考：<a href="https://opentelemetry.io/docs/collector/" target="_blank" rel="noreferrer">OpenTelemetry Collector</a> 与 <a href="https://opentelemetry.io/docs/what-is-opentelemetry/" target="_blank" rel="noreferrer">What is OpenTelemetry?</a></p></blockquote><p>OpenTelemetry 覆盖遥测数据的生成、上下文传播、接收、处理和导出，但它本身不是存储与查询后端。引入 Collector 的主要价值是把重试、批处理、路由、采样和敏感字段过滤从业务进程中解耦出来。</p><h2 id="cong-yong-hu-ti-yan-xuan-ze-zhi-biao" tabindex="-1">从用户体验选择指标 <a class="header-anchor" href="#cong-yong-hu-ti-yan-xuan-ze-zhi-biao" aria-label="Permalink to &quot;从用户体验选择指标&quot;">​</a></h2><h3 id="si-ge-huang-jin-xin-hao" tabindex="-1">四个黄金信号 <a class="header-anchor" href="#si-ge-huang-jin-xin-hao" aria-label="Permalink to &quot;四个黄金信号&quot;">​</a></h3><p>Google SRE 总结的四个黄金信号适合面向请求的在线服务：</p><ul><li><strong>延迟（Latency）</strong>：成功请求和失败请求的耗时应分开观察。</li><li><strong>流量（Traffic）</strong>：QPS、并发连接、消息消费速率等系统需求量。</li><li><strong>错误（Errors）</strong>：显式失败、错误结果和违反 SLO 的慢请求。</li><li><strong>饱和度（Saturation）</strong>：系统最受限资源的使用程度和排队情况。</li></ul><h3 id="red-yu-use" tabindex="-1">RED 与 USE <a class="header-anchor" href="#red-yu-use" aria-label="Permalink to &quot;RED 与 USE&quot;">​</a></h3><ul><li><strong>RED</strong> 适合服务端请求：Rate（速率）、Errors（错误）、Duration（耗时）。</li><li><strong>USE</strong> 适合资源：Utilization（利用率）、Saturation（饱和度）、Errors（错误）。</li></ul><p>不要为了完整而给每个组件堆满指标。先从用户可感知的 SLI 开始，再补充能够解释它的服务和资源指标。</p><h3 id="gao-ji-shu-wei-shi-me-wei-xian" tabindex="-1">高基数为什么危险 <a class="header-anchor" href="#gao-ji-shu-wei-shi-me-wei-xian" aria-label="Permalink to &quot;高基数为什么危险&quot;">​</a></h3><p>指标后端会为每种标签组合维护独立时间序列。<code>service</code>、<code>region</code>、<code>status_code</code> 通常有界；<code>user_id</code>、<code>order_id</code>、完整 URL 和 <code>trace_id</code> 可能几乎每次请求都不同，不适合作为普通指标标签。</p><p>需要从聚合指标跳到单次请求时，可以使用带 <code>trace_id</code> 的 exemplar，或者从日志、链路系统中检索，而不是把请求 ID 直接放进指标标签。</p><h2 id="yi-ci-kua-xin-hao-pai-zhang-shi-li" tabindex="-1">一次跨信号排障示例 <a class="header-anchor" href="#yi-ci-kua-xin-hao-pai-zhang-shi-li" aria-label="Permalink to &quot;一次跨信号排障示例&quot;">​</a></h2><p>假设“创建订单”的 P99 延迟突然从 300 ms 升到 2 s：</p><ol><li><strong>指标</strong>确认异常只发生在 <code>region=cn-east</code>、<code>version=2.3.1</code>，错误率没有明显上升。</li><li>从延迟直方图的 <strong>exemplar</strong> 跳转到一条慢 Trace。</li><li><strong>链路</strong>显示库存服务本身只执行了 80 ms，但调用前出现 1.4 s 的排队空白。</li><li><strong>日志</strong>通过相同 <code>trace_id</code> 找到连接池获取超时，并确认没有记录密码或数据库连接串。</li><li><strong>部署事件</strong>显示该区域刚把连接池上限从 100 调成 20。</li><li>修复配置后，用同一组 SLI 验证 P99 和饱和度恢复。</li></ol>',15)),(t(),r(d,null,{default:a(()=>[l(i,{id:"mermaid-277",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22SLO%20%E5%91%8A%E8%AD%A6%3Cbr%3EP99%20%E5%BB%B6%E8%BF%9F%E5%8D%87%E9%AB%98%22%5D%20--%3E%20B%5B%22%E6%8C%87%E6%A0%87%E7%BC%A9%E5%B0%8F%E8%8C%83%E5%9B%B4%3Cbr%3E%E5%8C%BA%E5%9F%9F%E3%80%81%E7%89%88%E6%9C%AC%E3%80%81%E6%8E%A5%E5%8F%A3%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22Exemplar%20%E6%88%96%E6%9F%A5%E8%AF%A2%3Cbr%3E%E6%89%BE%E5%88%B0%E4%BB%A3%E8%A1%A8%E6%80%A7%20Trace%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Trace%20%E7%A1%AE%E5%AE%9A%E5%85%B3%E9%94%AE%E8%B7%AF%E5%BE%84%3Cbr%3E%E5%AE%9A%E4%BD%8D%E6%85%A2%20Span%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E6%8C%89%20trace_id%20%2F%20span_id%3Cbr%3E%E5%85%B3%E8%81%94%E7%BB%93%E6%9E%84%E5%8C%96%E6%97%A5%E5%BF%97%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E5%AF%B9%E7%85%A7%E9%83%A8%E7%BD%B2%E4%B8%8E%E9%85%8D%E7%BD%AE%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%E5%BD%A2%E6%88%90%E5%B9%B6%E9%AA%8C%E8%AF%81%E6%95%85%E9%9A%9C%E5%81%87%E8%AE%BE%22%5D%0A%20%20%20%20G%20--%3E%20H%7B%22SLI%20%E6%98%AF%E5%90%A6%E6%81%A2%E5%A4%8D%EF%BC%9F%22%7D%0A%20%20%20%20H%20--%3E%7C%E6%98%AF%7C%20I%5B%22%E8%AE%B0%E5%BD%95%E7%BB%93%E8%AE%BA%E5%B9%B6%E8%A1%A5%E5%85%85%E9%98%B2%E6%8A%A4%22%5D%0A%20%20%20%20H%20--%3E%7C%E5%90%A6%7C%20B%0A%20%20%20%20C%20--%3E%20J%7B%22%E9%93%BE%E8%B7%AF%E6%98%AF%E5%90%A6%E6%96%AD%E8%A3%82%EF%BC%9F%22%7D%0A%20%20%20%20J%20--%3E%7C%E6%98%AF%7C%20K%5B%22%E4%BF%AE%E5%A4%8D%E5%9F%8B%E7%82%B9%E6%88%96%E4%B8%8A%E4%B8%8B%E6%96%87%E4%BC%A0%E6%92%AD%22%5D%0A%20%20%20%20K%20--%3E%20C%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<blockquote><p>图示参考：<a href="https://opentelemetry.io/docs/concepts/observability-primer/" target="_blank" rel="noreferrer">OpenTelemetry Observability Primer</a> 与 <a href="https://sre.google/sre-book/monitoring-distributed-systems/" target="_blank" rel="noreferrer">Google SRE：Monitoring Distributed Systems</a></p></blockquote><p>这个过程依赖共同的资源属性，如 <code>service.name</code>、<code>service.version</code>、<code>deployment.environment.name</code> 和 <code>cloud.region</code>。如果各团队使用不同字段名，即使数据都已采集，也难以可靠关联。</p><h2 id="mai-dian-yu-shu-ju-jian-mo-yuan-ze" tabindex="-1">埋点与数据建模原则 <a class="header-anchor" href="#mai-dian-yu-shu-ju-jian-mo-yuan-ze" aria-label="Permalink to &quot;埋点与数据建模原则&quot;">​</a></h2><h3 id="tong-yi-zi-yuan-yu-shu-xing" tabindex="-1">统一资源与属性 <a class="header-anchor" href="#tong-yi-zi-yuan-yu-shu-xing" aria-label="Permalink to &quot;统一资源与属性&quot;">​</a></h3><p>优先采用 OpenTelemetry Semantic Conventions 等公共约定，并为内部业务字段制定稳定规范。属性应描述实际语义，而不是绑定某个后端的查询写法。</p><h3 id="zi-dong-mai-dian-yu-shou-dong-mai-dian-jie-he" tabindex="-1">自动埋点与手动埋点结合 <a class="header-anchor" href="#zi-dong-mai-dian-yu-shou-dong-mai-dian-jie-he" aria-label="Permalink to &quot;自动埋点与手动埋点结合&quot;">​</a></h3><p>自动埋点适合 HTTP、RPC、数据库和常见框架调用；手动埋点用于“创建订单”“库存预占”等业务边界。只有技术 Span 而没有业务语义，往往只能看到调用慢，却无法判断业务是否正确。</p><h3 id="kong-zhi-cheng-bener-bu-shi-mang-mu-shao-cai" tabindex="-1">控制成本，而不是盲目少采 <a class="header-anchor" href="#kong-zhi-cheng-bener-bu-shi-mang-mu-shao-cai" aria-label="Permalink to &quot;控制成本，而不是盲目少采&quot;">​</a></h3><ul><li>指标：限制标签基数，优先使用直方图观察延迟分布。</li><li>链路：用头部采样控制基础流量，用尾部采样保留错误和高延迟请求。</li><li>日志：按查询价值决定级别、字段和保留周期，不把 DEBUG 永久留在生产环境。</li><li>全部信号：尽早过滤密钥、Token 和个人敏感信息。</li></ul><h3 id="jian-kong-yao-ce-guan-dao-zi-shen" tabindex="-1">监控遥测管道自身 <a class="header-anchor" href="#jian-kong-yao-ce-guan-dao-zi-shen" aria-label="Permalink to &quot;监控遥测管道自身&quot;">​</a></h3><p>采集器丢数据时，业务看板可能看似“恢复正常”。因此还要监控 Collector 的接收拒绝量、导出失败量、队列使用量、处理延迟和资源占用。</p><h2 id="zui-xiao-luo-di-lu-xian" tabindex="-1">最小落地路线 <a class="header-anchor" href="#zui-xiao-luo-di-lu-xian" aria-label="Permalink to &quot;最小落地路线&quot;">​</a></h2><ol><li>为一条关键用户旅程定义 SLI、SLO 和错误预算。</li><li>统一服务名、环境、版本、区域等资源属性。</li><li>接入 HTTP/RPC 自动埋点，并补充少量业务 Span。</li><li>输出结构化日志，自动注入 <code>trace_id</code> 和 <code>span_id</code>。</li><li>通过 Collector 集中完成批处理、重试、过滤和导出。</li><li>建立 RED 看板，并只对用户影响和 SLO 消耗告警。</li><li>演练一次真实故障，验证能否从指标跳到 Trace，再关联到日志和变更事件。</li></ol><h2 id="xue-xi-zi-ce" tabindex="-1">学习自测 <a class="header-anchor" href="#xue-xi-zi-ce" aria-label="Permalink to &quot;学习自测&quot;">​</a></h2><ol><li>为什么“部署了 Prometheus、Loki 和 Jaeger”不等于具备可观测性？</li><li><code>user_id</code> 为什么通常不适合作为指标标签，却可以作为受控的日志字段？</li><li>自动埋点已经覆盖 HTTP 调用时，为什么还需要业务 Span？</li><li>遥测 Collector 停止导出时，应该由哪些独立信号发现？</li></ol><h2 id="yan-shen-yue-du" tabindex="-1">延伸阅读 <a class="header-anchor" href="#yan-shen-yue-du" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>OpenTelemetry：<a href="https://opentelemetry.io/docs/concepts/observability-primer/" target="_blank" rel="noreferrer">Observability Primer</a></li><li>OpenTelemetry：<a href="https://opentelemetry.io/docs/what-is-opentelemetry/" target="_blank" rel="noreferrer">What is OpenTelemetry?</a></li><li>OpenTelemetry：<a href="https://opentelemetry.io/docs/collector/" target="_blank" rel="noreferrer">Collector</a></li><li>OpenTelemetry：<a href="https://opentelemetry.io/docs/concepts/semantic-conventions/" target="_blank" rel="noreferrer">Semantic Conventions</a></li><li>Google SRE Book：<a href="https://sre.google/sre-book/monitoring-distributed-systems/" target="_blank" rel="noreferrer">Monitoring Distributed Systems</a></li></ul>',17))])}const _=E(c,[["render",u]]);export{y as __pageData,_ as default};
